p01-balance:
def solve(initial, durations, inflows, outflows):
    result=[initial]
    for h,u,v in zip(durations,inflows,outflows):
        result.append(result[-1]+h*(u-v))
    return result

p01-loop-sign:
def solve(signs):
    result=1
    for s in signs:
        result*=s
    return result

p01-turn-count:
def solve(values):
    directions=[1 if b>a else -1 for a,b in zip(values,values[1:]) if abs(b-a)>1e-12]
    return sum(a!=b for a,b in zip(directions,directions[1:]))

p01-compare-rules:
def solve(initial, fixed, fraction, steps):
    a,b=[initial],[initial]
    for _ in range(steps):
        a.append(a[-1]-fixed)
        b.append(b[-1]*(1-fraction))
    return a,b

p01-first-failure:
def solve(initial, fixed, steps):
    for i in range(1,steps+1):
        if initial-i*fixed<0:
            return i
    return -1

p01-cap-count:
def solve(initial, entered, left, born):
    counts=[initial]
    for u,v,b in zip(entered,left,born):
        counts.append(counts[-1]+u-v+b)
    return counts
